      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string', description: 'Substring to match against record names (case-insensitive).' },
          limit: { type: 'integer', minimum: 1, maximum: 4, default: 2, description: 'Maximum number of matching records to return (1..4).' }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'search_records') {
    throw new Error('Unknown tool: ' + name);
  }

  const known = { query: true, limit: true };
  for (const key of Object.keys(args)) {
    if (!known[key]) {
      throw Object.assign(new Error('Unexpected argument: ' + key), { code: -32602 });
    }
  }

  assert(typeof args.query === 'string', 'query must be a string');

  let limit = 2;
  if (args.limit !== undefined) {
    assert(Number.isInteger(args.limit), 'limit must be an integer');
    assert(args.limit >= 1 && args.limit <= 4, 'limit must be between 1 and 4');
